CREATE PROCEDURE public.sp_restore_product(IN p_product_id integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM tb_products WHERE id = p_product_id) THEN
        RAISE EXCEPTION 'El producto especificado no existe' USING ERRCODE = '45000';
    END IF;

    IF EXISTS (SELECT 1 FROM tb_products WHERE id = p_product_id AND status = B'1') THEN
        RAISE EXCEPTION 'El producto ya se encuentra activo' USING ERRCODE = '45000';
    END IF;

    UPDATE tb_products SET status = B'1' WHERE id = p_product_id;
END;
$$;


